    inline bool Matches()
    {
        const auto module = GetModuleHandleW(nullptr);
        if (reinterpret_cast<uintptr_t>(module) != 0x400000 || !Readable(module, sizeof(IMAGE_DOS_HEADER)))
            return false;
        const auto dos = static_cast<const IMAGE_DOS_HEADER*>(static_cast<const void*>(module));
        if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew <= 0 || dos->e_lfanew > 4096)
            return false;
        const auto nt = reinterpret_cast<const IMAGE_NT_HEADERS32*>(static_cast<const uint8_t*>(static_cast<const void*>(module)) + dos->e_lfanew);
        if (!Readable(nt, sizeof(*nt)) || nt->Signature != IMAGE_NT_SIGNATURE ||
            nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386 || nt->OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR32_MAGIC ||
            nt->OptionalHeader.SizeOfImage != 0x4E5000)
            return false;
        for (const auto& entry : Entries)
            if (!Readable(reinterpret_cast<void*>(entry.address), entry.bytes.size()) ||
                std::memcmp(reinterpret_cast<void*>(entry.address), entry.bytes.data(), entry.bytes.size()))
                return false;
        return true;
    }
